ce":"placeholder"},"stats":[{"value":"20+","label":"Jahre Erfahrung"},{"value":"1.200+","label":"Aufträge"},{"value":"24 h","label":"Notdienst"}]}},{"component_type":"team","variant":"cards","content":{"headline":"Ihre Ansprechpartner","members":[{"name":"Herr Weber","role":"Inhaber und Ansprechpartner"},{"name":"[Name ergänzen]","role":"[Funktion ergänzen]"}]}},{"component_type":"gallery","variant":"grid","content":{"headline":"Einblicke in unsere Arbeit","intro":"Eine Auswahl aus aktuellen Projekten.","items":[{"image":{"slot_id":"gallery-1","alt":"Fertige Elektroinstallation","source":"placeholder"},"caption":"Neuer Verteilerschrank im Einfamilienhaus"},{"image":{"slot_id":"gallery-2","alt":"Beleuchtung im Treppenhaus","source":"placeholder"},"caption":"Beleuchtung im Treppenhaus"},{"image":{"slot_id":"gallery-3","alt":"Ladestation an einer Garage","source":"placeholder"},"caption":"Ladestation für ein Elektroauto"}]}},{"component_type":"testimonials","variant":"cards-grid","content":{"headline":"Das sagen unsere Kunden","items":[{"name":"Beispielkundin A.","quote":"Pünktlich, freundlich und sauber gearbeitet. Gern wieder.","rating":5},{"name":"Beispielkunde B.","quote":"Der Fehler war nach einer Stunde gefunden. Faire Rechnung.","rating":5},{"name":"Beispielkundin C.","quote":"Gute Beratung zum Smart Home, ohne etwas aufzuschwatzen.","rating":4}]}},{"component_type":"faq","variant":"accordion","content":{"headline":"Häufige Fragen","items":[{"question":"Wie schnell bekomme ich einen Termin?","answer":"In der Regel innerhalb einer Woche. Bei Störungen versuchen wir, am selben Tag zu helfen."},{"question":"Was kostet ein Besuch?","answer":"Nach einer Besichtigung nennen wir einen Festpreis. Kleinere Reparaturen rechnen wir nach Aufwand ab."}]}},{"component_type":"footer","variant":"standard","content":{"company_name":"Elektro Weber","tagline":"Elektrotechnik für Haus und Betrieb in Lahr und Umgebung.","address":"Hauptstraße 12\n77933 Lahr","phone":"07821 555 0101"